package com.onlinemedic.controller;
import com.onlinemedic.model.User;import com.onlinemedic.util.Database;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.util.*;
@WebServlet("/notifications")
public class NotificationsServlet extends HttpServlet{
 @Override protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");if(u==null){s.sendRedirect(q.getContextPath()+"/login");return;}try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,title,body,created_at,read_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100")){p.setLong(1,u.id());try(ResultSet r=p.executeQuery()){List<Map<String,Object>> list=new ArrayList<>();while(r.next()){Map<String,Object> m=new HashMap<>();m.put("id",r.getLong(1));m.put("title",r.getString(2));m.put("body",r.getString(3));m.put("createdAt",r.getTimestamp(4));m.put("read",r.getTimestamp(5)!=null);list.add(m);}q.setAttribute("notifications",list);}q.getRequestDispatcher("/WEB-INF/views/notifications.jsp").forward(q,s);}catch(Exception e){throw new ServletException("Notifications are unavailable.",e);}}
 @Override protected void doPost(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("UPDATE notifications SET read_at=CURRENT_TIMESTAMP WHERE user_id=? AND read_at IS NULL")){p.setLong(1,u.id());p.executeUpdate();q.getSession().setAttribute("flashSuccess","Notifications marked as read.");s.sendRedirect(q.getContextPath()+"/notifications");}catch(Exception e){throw new ServletException("Notifications could not be updated.",e);}}
}
